def find_rectangle_segments(nums):
    minimum = nums[0]
    for num in nums[1:]:
        minimum = [[min(x) for x in zip(minimum, num[0])], [min(x) for x in zip(max(minimum[0]), max(num[0]))], 
                   [min(x) for x in zip(minimum[1], num[1])], [min(x) for x in zip(max(minimum[1]), max(num[1]))]]
