MOD = 1000000007

def compute_G_cols(X, Y):
    l = len(X)
    G = [[0] * l for _ in range(l)]

    for i in range(l):
        if (X[i], Y[i]) != (0, 0):
            g = 0
            for j in range(l):
                if (X[i], Y[j]) != (0, 0):
                    if not (X[j] == X[i] and Y[j] == Y[i]):
                        G[i][j] = g
                        for k in range(l):
                            if (X[k], Y[k]) != (0, 0):
                                if (G[i][j] + G[j][k]) % 2 == 0:
                                    return g
                        g += 1
    return g

def parity(Z):
