def count_final_configurations(N, M):
    graph = defaultdict(list)
    for u, v in zip(*[iter(range(1, N+1))] * 2):
        graph[u] += [v]
        graph[v] += [u]

    def dfs(start, visited, paths):
        paths[start] = ''.join(paths[node] for node in paths if node in visited)
        visited.add(start)
        for nex in graph[start]:
            if nex not in visited:
                dfs(nex, visited, paths)

    configs = 1
    for i in range(N):
        start = N + 1 - i
        visited = {start}
        paths = defaultdict(list)
        paths[start] += ' '
        for num, _ in enumerate(graph[start], start+1):
            paths[num] = ''
        dfs(start, visited, paths)
        for path in paths:
            if path:
                configs *= len(set(map(reversed, map(collections.deque, path)))-{''})
        configs *= pow(2, len(graph[1]) - len(visited) if N % 2 != 0 else len(graph[1]), 1000000007, 1000000007)

