MOD = 10**9 + 7

def find(parent, i):
    if parent[i] == i:
        return i
    else:
        return find(parent, parent[i])

def union(parent, ranks, i, j):
    root1 = find(parent, i)
    root2 = find(parent, j)
    if root1 != root2:
        if ranks[root1] < ranks[root2]:
            parent[root1] = root2
        elif ranks[root1] > ranks[root2]:
            parent[root2] = root1
        else:
            parent[root2] = root1
            ranks[root1] += 1

