def calculate_shortest_path(graph, start):
    distances = {city: float('inf') for city in range(1, n + 1)}
    distances[start] = 0

    queue = [(0, start)]

    while queue:
        current_distance, current_city = queue.pop(0)
        if current_distance >= distances[current_city]:
            continue

        for neighbor in graph[current_city]:
            if distances[neighbor] > current_distance + 1:
                distances[neighbor] = current_distance + 1
                queue.append((distances[neighbor], neighbor))

    return distances

def find_unhappy_friends(graph, start, end):
    if len(graph[end]) == 0:
        return False, 0

    shortest_path = calculate_shortest_path(graph, start)
    unhappy_count = 0

    for city, distance in shortest_path.items():
        if distance >= shortest_path[end]:
            unhappy_count += 1

    return True, unhappy_count

