def find_smallest_n(C, P):
    if P == 2:
        if C == 0:
            return 0
        return -1
    if C == 0:
        primes = [i for i in range(P) if is_prime(2*i+1)]
        return C if P in primes else -1
    if C == 1:
        primes = [i for i in range(P) if is_prime(2*i+1)]
        return P-2 if P in primes else -1
    if P % 4 == 3:
        return 0 if C == 0 else -1
    k = (P-1)*(P-1+4) if P-1 % 4 == 3 else (P-1)*(P-1) - 4
    return (C - k) % P

