from collections import defaultdict

def create_spanning_tree(edges):
    graph = defaultdict(list)
    for a, b in edges:
        graph[a].append((b, a))
        graph[b].append((a, b))
    return graph

def count_happy_pairs(graph, weights, n):
    # Calculate the height of each node in the tree
    heights = {}
    for u in range(1, n+1):
        heights[u] = -1

    # Topological sort using DFS
    order = []
    for u in graph:
        order.append(u)
    stack = []
    order.append(0)  # Pretend root node falls here due to disconnectedness
    while stack or order:
        if order:
            u = order.pop(0)
            if u not in graph:
                stack.append(u)
        else:
            for v, _ in graph[u]:
                heights[v] = max(heights[v], heights[u] + 1)
                if v in graph:
                    order.append(v)

    result = [0] * n

    # Process edges in reverse order of DFS discovery
    stack = [(1, weights[1] + 1)]
    seen = set()
    seen.add(1)

    for v, weight in stack:
        match = weights[v] > weight
        for a, b in graph[v]:
            if heights[a] < heights[b] or (weights[a] - weights[v]) % 2 == 0 and (weights[b] - weights[v]) % 2 == 1:
                match = False
        if match:
            if weights[v] > weight:
                result[v] -= 1
            else:
                result[v] += 1
        for e in graph[v]:
            if e[0] in seen:
                stack.append(e)
            else:
                seen.add(e[0])
                stack.append(e)
                seen.add(e[1])
                stack.append((e[1], weight + 2))

    return result

