def find_chore_sequence(n, x0, y0, light_info):
    from collections import deque
    dx, dy = [1, -1, 0, 0], [0, 0, 1, -1]
    visited = [[False] * n for _ in range(n)]
    dqs = [deque() for _ in range(4)]
    visited[x0-1][y0-1] = True
    dqs[0].append((x0-1, y0-1, 1))  # Up possible direction
    queue = deque([(x0-1, y0-1, 1)])  # BFS queue

    step = 1
    while queue:
        for _ in range(len(queue)):
            x, y, dir_ = queue.popleft()
            for i in range(4):
                nx, ny = x + (dx[i] * step), y + (dy[i] * step)
                if 0 <= nx < n and 0 <= ny < n and not visited[nx][ny]:
                    if light_info[nx][ny] and i != dir_ - 1:
                        if dir_ == 'R' or dir_ == 'U':
                            dqs[i % 4].append((nx, ny, i))
                            visited[nx][ny] = True
                        elif dir_ == 'L' or dir_ == 'D':
                            dqs[i % 4][0].append((nx, ny, i))
                            visited[nx][ny] = True
                    else:
                        dqs[i % 4].append((nx, ny, dir_) if not (i == 1 and light_info[nx][ny]) else (nx, ny, (i-1) % 4))
                        visited[nx][ny] = True
                    queue.append((nx, ny, i))
        if len(dqs[0]) > 1:
            dqs[0].rotate(-1)
        elif len(dqs[2]) > 1:
            dqs[2].rotate(-1)

    path = []
    x, y, action = x0-1, y0-1, -1
    for i in range(4):
        while dqs[i]:
            nx, ny, ouit = dqs[i].popleft()
            if not visited[nx][ny]:
                path.append(('D' if ouit == 1 else 'U') + dqs[i % 4][0].popleft()[0] if ouit == 3 or ouit == 4 else 'U')
                visited[nx][ny] = True
            if ouit == 3:
                x, y = nx, ny
    if len(path) != step * 4:
        return "NO"
    else:
        return "YES\n".join(path)

