from functools import lru_cache

def longest_common_subsequence_length(x, y):
    @lru_cache(maxsize=None)
    def LCS(i, j):
        if i == -1 or j == -1:
            return 0
        if x[i] == y[j]:
            return 1 + LCS(i - 1, j - 1)
        else:
            return max(LCS(i - 1, j), LCS(i, j - 1))

    # Calculate LCS length for each prefix up to the full string
    prefix_lcs_counts = [LCS(i, i) for i in range(len(x) + 1)]

    # There are two ways to form a string of length n with LCS length n-1:
    # 1. Starting with the first character of x and appending the rest of y
    # 2. Starting with the first character of y and appending the rest of x
    total_lcs_counts = 2 * (prefix_lcs_counts[-1] - 1)
    # Add the case where all characters from the first position onwards are the same
    total_lcs_counts += min(prefix_lcs_counts)

    return total_lcs_counts

