def count_unique_string(m, s):
    dp = [[0] * (m + 1) for _ in range(m + 1)]
    for i in range(1, len(s) + 1):
        for j in range(1, m + 1):
            if s[i - 1] == list('a' + 'b' + 'c')(j):
                dp[j][i] = dp[j - 1][i - 1] + 1
            elif dp[j][i - 1] > 0:
                dp[j][i] = dp[j - 1][i]
            elif dp[j][i] > 0:
                dp[j][i] = dp[j][i - 1]
            else:
                dp[j][i] = 0
    same_count = max(dp[j][len(s)] for j in range(1, m + 1))
    result = 10 ** 8
    for num in dp[1][1:]:
        result += max(num - 1, 0)
