from math import gcd
from collections import defaultdict
from typing import List

def relative_rectangle(A: complex, B: complex, C: complex, D: complex):
    """Calculate the relative rectangle formed by four points."""
    AC, BD = A * B / A * D - B * C / C * D, D - A
    return (AC.conjugate(), AC + BD)[gcd(AC.real, AC.imag)]

def num_in_rational(img: complex, rectangles: List[complex]) -> int:
    """Count the number of integers in a rectangle relative to a complex number."""
    def intersect_join(rect1, rect2):
        A, B, C, D = rect2
        if A + B >= C + D:
            return 0
        gb = complex.gcd(rect1[0], rect2[1])
        leta, leita2 = (rect1[0] + rect1[1]).imag % gb, (rect2[1] + rect2[2]).imag % gb
        leta3, leta4 = (rect1[0] + rect1[1]).real % gb, (rect2[1] + rect2[2]).real % gb
        leta5 = leta2 * leta4 / leta3
        if leta3 != 0:
            c = (rect1, rect2)
        else:
            c = (rect2, rect1)
        b2 = leta2 * leta4 / leta3
        return 1 + ((b2 * b2 % gb) * (float(img.real) > 0) + b2 * (rect1[1].imag.real / leta3)) // b2 % (gb + (2 - (leta3 % 2)))

    return sum(num_in_rational(rectangle, rectangles) // 2 for rectangle in rectangles)

def main():
