import sys

def count_lcs(n, m, s):
    dp = [[0] * m for _ in range(n)]

    for i in range(n):
        for j in range(m):
            if i == 0 or j == 0:
                dp[i][j] = 1
            elif s[i-1] == s[j-1]:
                dp[i][j] = dp[i-1][j-1] + 2
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    # Total strings of length n start with any of the m characters
    total_strings = m ** n
    # Subtract the case where all characters are distinct (LCS of length 0)
    return total_strings - dp[n-1][m-1]

if __name__ == "__main__":
    n, m = map(int, input().split())
    s = input()
    print(count_lcs(n, m, s))
